Clipboard e feedback "Copiado!" exigem estado — client component com "use client". Detalhes que separam o bom do meia-boca aqui: o botão tem largura FIXA (w-24) pra não pular de tamanho quando o texto troca de "Copiar" pra "Copiado!"; o input é readOnly com fonte mono (valor técnico) e fundo rebaixado sinalizando não-editável; o feedback reverte sozinho após 2s. navigator.clipboard é async — o handler acompanha:
<tool_call>
{"name": "write_file", "arguments": {"path": "components/CopyField.tsx", "content": ""use client";

import { useState } from "react";

type CopyFieldProps = {
  value: string;
  label: string;
};

export default function CopyField({ value, label }: CopyFieldProps) {
  const [copied, setCopied] = useState(false);

  async function copy() {
    await navigator.clipboard.writeText(value);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }

  return (
    <div className="space-y-1.5">
      <label className="text-sm font-medium">{label}</label>
      <div className="flex gap-2">
        <input
          readOnly
          value={value}
          aria-label={label}
          className="h-10 flex-1 rounded-xl border border-zinc-300 bg-zinc-50 px-3 font-mono text-sm text-zinc-600 outline-none focus-visible:ring-2 focus-visible:ring-zinc-500 dark:border-zinc-700 dark:bg-zinc-900 dark:text-zinc-400"
        />
        <button
          type="button"
          onClick={copy}
          className="h-10 w-24 rounded-xl border border-zinc-300 text-sm font-medium transition-colors hover:bg-zinc-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-zinc-500 dark:border-zinc-700 dark:hover:bg-zinc-800"
        >
          {copied ? "Copiado!" : "Copiar"}
        </button>
      </div>
    </div>
  );
}
"}}
</tool_call>

