Full audit — six fixes in one rewrite:
1. the ask: threshold tones — green below 70%, amber to 89%, rose at 90%+ (semantic color doing the warning work);
2. unclamped math: used > limit renders a bar past 100% — clamp it;
3. square everything → rounded-full track with overflow-hidden so the fill respects the radius;
4. no dark mode on the track → dark:bg-zinc-800;
5. no a11y: this is a progressbar → role + aria-valuenow/min/max + label;
6. label line upgraded: name in medium weight, "used / limit GB · %" right-aligned in tabular-nums, plus a width transition so updates glide instead of jumping.
Writing it:
<tool_call>
{"name": "write_file", "arguments": {"path": "components/UsageMeter.tsx", "content": "export default function UsageMeter({ used, limit }: { used: number; limit: number }) {
  const pct = Math.min(100, Math.round((used / limit) * 100));
  const tone =
    pct >= 90
      ? "bg-rose-500"
      : pct >= 70
        ? "bg-amber-500"
        : "bg-emerald-500";
  return (
    <div className="space-y-1.5">
      <div className="flex items-baseline justify-between text-sm">
        <span className="font-medium">Storage</span>
        <span className="tabular-nums text-zinc-500 dark:text-zinc-400">
          {used} / {limit} GB · {pct}%
        </span>
      </div>
      <div
        role="progressbar"
        aria-valuenow={pct}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-label={`Uso de armazenamento: ${pct}%`}
        className="h-2 w-full overflow-hidden rounded-full bg-zinc-200 dark:bg-zinc-800"
      >
        <div
          className={`h-full rounded-full transition-[width] duration-300 ${tone}`}
          style={{ width: `${pct}%` }}
        />
      </div>
    </div>
  );
}
"}}
</tool_call>

